","background":"transparent"}},{"type":"log","x":0,"y":2,"width":12,"height":6,"properties":{"query":"filter Shutdowns = 1 | fields ShutdownLapse / 1000 as shutdownLapseSec | stats avg(shutdownLapseSec) as AvgShutdownLapseSec, percentile(shutdownLapseSec, 50) as P50, percentile(shutdownLapseSec, 90) as P90 by bin(1h)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Shutdown Lapse Trend","log_group_names":["${LogGroupName}"]}},{"type":"log","x":12,"y":2,"width":12,"height":6,"properties":{"query":"filter Environment = 1 | stats count(*) as ColdStarts by bin(5m)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Cold Start Rate Over Time","log_group_names":["${LogGroupName}"]}},{"type":"log","x":0,"y":8,"width":12,"height":6,"properties":{"query":"filter Invokes = 1 | stats count(*) as InvocationsPerMin by bin(1m)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Invocation Rate Trend","log_group_names":["${LogGroupName}"]}},{"type":"log","x":12,"y":8,"width":12,"height":6,"properties":{"query":"filter Shutdowns = 1 | stats count(*) as EnvCount, avg(TotalLifetime) / 1000 / 60 as AvgLifetimeMin, avg(TotalInvokes) as AvgInvokes by case( TrafficDropRate < 25, '1. Low (<25%)', TrafficDropRate >= 25 and TrafficDropRate < 50, '2. Moderate (25-50%)', TrafficDropRate >= 50 and TrafficDropRate < 75, '3. High (50-75%)', TrafficDropRate >= 75, '4. Severe (>75%)' ) as TrafficDrop","region":"${Region}","stacked":false,"view":"bar","title":"Traffic Drop Rate vs Avg Lifetime","log_group_names":["${LogGroupName}"]}},{"type":"log","x":0,"y":14,"width":12,"height":6,"properties":{"query":"filter Invokes = 1 and MemoryUtilizationPct > 0 | stats avg(MemoryUtilizationPct) as AvgMemUtil, max(MemoryUtilizationPct) as MaxMemUtil, percentile(MemoryUtilizationPct, 90) as P90MemUtil by bin(5m)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Memory Utilization Per Invocation","log_group_names":["${LogGroupName}"]}},{"type":"log","x":12,"y":14,"width":12,"height":6,"properties":{"query":"filter Invokes = 1 and BilledDuration > 0 | stats avg(BilledDuration) as AvgDuration, percentile(BilledDuration, 50) as P50, percentile(BilledDuration, 90) as P90, percentile(BilledDuration, 99) as P99 by bin(5m)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Billed Duration Per Invocation","log_group_names":["${LogGroupName}"]}},{"type":"log","x":0,"y":20,"width":12,"height":6,"properties":{"query":"filter Invokes = 1 and IdleGap >= 0 | fields IdleGap / 1000 as idleGapSec | stats count(*) as occurrences by case( idleGapSec < 1, '1. < 1s', idleGapSec >= 1 and idleGapSec < 5, '2. 1-5s', idleGapSec >= 5 and idleGapSec < 15, '3. 5-15s', idleGapSec >= 15 and idleGapSec < 30, '4. 15-30s', idleGapSec >= 30 and idleGapSec < 60, '5. 30-60s', idleGapSec >= 60 and idleGapSec < 120, '6. 1-2 min', idleGapSec >= 120, '7. 2+ min' ) as IdleGapBucket","region":"${Region}","stacked":false,"view":"bar","title":"Idle Gap Distribution (Detailed)","log_group_names":["${LogGroupName}"]}},{"type":"log","x":12,"y":20,"width":12,"height":6,"properties":{"query":"filter Invokes = 1 and IdleGap >= 0 | stats avg(IdleGap) / 1000 as AvgIdleGapSec, percentile(IdleGap / 1000, 50) as P50Sec, percentile(IdleGap / 1000, 90) as P90Sec by bin(5m)","region":"${Region}","stacked":false,"view":"timeSeries","title":"Idle Gap Trend Over Time","log_group_names":["${LogGroupName}"]}},{"type":"log","x":0,"y":26,"width":8,"height":6,"properties":{"query":"filter Shutdowns = 1 | stats count(*) as totalShutdowns, sum(IsColdStart) as totalColdStarts, avg(ColdStartOverhead) as avgColdStartOverheadMs, sum(ColdStartOverhead) / 1000 as totalColdStartOverheadSec, avg(AllocatedMemory) as avgMemoryMB, avg(TotalInvokes) as avgInvokesPerEnv, avg(TotalLifetime) / 1000 / 60 as avgLifetimeMin","region":"${Region}","stacked":false,"view":"table","title":"Cold Start Cost Impact Summary","log_group_names":["${LogGroupName}"]}},{"type":"log","x":8,"y":26,"width":8,"height":6,"properties":{"query":"filter Shutdowns = 1 | stats max(PeakRequestsPerMinute) as overallPeakRPM, avg(PeakRequestsPerMinute) as avgPeakRPM, percentile(PeakRequestsPerMinute, 90) as p90PeakRPM, avg(AvgBilledDuration) as avgDurationMs, avg(InvokeRate) as avgInvokeRate, count(*) as totalEnvironments, avg(AllocatedMemory) as memoryMB","region":"${Region}","stacked":false,"view":"table","title":"Provisioned Concurrency Sizing Data","log_group_names":["${LogGroupName}"]}},{"type":"log","x":16,"y":26,"width":8,"height":6,"properties":{"query":"filter Shutdowns = 1 and @properties.ShutdownReason = 'SPINDOWN' | stats count(*) as spindownCount, avg(AvgIdleGap) / 1000 as avgIdleGapSec, percentile(AvgIdleGap / 1000, 50) as p50IdleGapSec, percentile(AvgIdleGap / 1000, 90) as p90IdleGapSec, avg(ShutdownLapse) / 1000 as avgShutdownLapseSec, percentile(ShutdownLapse / 1000, 10) as p10ShutdownLapseSec, percentile(ShutdownLapse / 1000, 50) as p50ShutdownLapseSec","region":"${Region}","stacked":false,"view":"table","title":"Keep-Alive Interval Estimation","log_group_names":["${LogGroupName}"]}}]}
